<?phpnamespace app\common\model;/** * 规格/属性(组)模型 */class Spec extends BaseModel{    // 定义表名    protected $name = 'spec';    protected $updateTime = false;    // 定义主键    protected $pk = 'spec_id';        // 追加字段    protected $append = [];    /**     * 根据规格组名称查询规格id     */    public function getSpecIdByName(string $spec_name)    {        return $this->where(compact('spec_name'))->value('spec_id');    }    /**     * 新增规格组     */    public function add(string $spec_name)    {        return $this->save(compact('spec_name'));    }}